#!/usr/bin/env node
/**
 * Pixel-art mascot generator ("Yamaç" – the portfolio's roaming assistant).
 *
 * Draws the character from ASCII bitmaps (character.mjs), composes animation frames
 * (frames.mjs) and writes:
 *   mascot.png        sprite sheet: one row per animation, one column per frame
 *   mascot-bust.png   24x24 head-and-shoulders crop for avatars
 *   mascot.meta.ts    generated frame metadata for the app (do not edit)
 *   mascot.behaviors.ts  generated behaviour table for the assistant engine (from behaviors.mjs)
 *
 * Usage:
 *   node scripts/sprites/build-sprites.mjs                    # writes src/assets/sprites/*
 *   node scripts/sprites/build-sprites.mjs --out some/dir     # custom output dir
 *   node scripts/sprites/build-sprites.mjs --preview out.png  # also writes an enlarged contact sheet
 *
 * No dependencies (the PNG encoder uses node:zlib).
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { Bmp, encodePNG, rgba, scaleNearest } from './lib.mjs';
import { FH, FW } from './character.mjs';
import { ANIMS, FPS } from './frames.mjs';
import { BEHAVIORS } from './behaviors.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const argVal = (name) => {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : undefined;
};
const OUT_DIR = path.resolve(argVal('--out') ?? path.join(here, '../../src/assets/sprites'));
const PREVIEW = argVal('--preview');

const names = Object.keys(ANIMS);
const cols = Math.max(...names.map((n) => ANIMS[n].length));
const rows = names.length;

for (const n of names) for (const f of ANIMS[n]) if (f.w !== FW || f.h !== FH) throw new Error(`${n}: bad frame size`);

/* ---- sprite sheet ---- */
const sheet = new Bmp(cols * FW, rows * FH);
names.forEach((n, r) => ANIMS[n].forEach((f, c) => sheet.paste(f, c * FW, r * FH)));

/* ---- bust (head + shoulders) ---- */
const bust = new Bmp(24, 24);
const idle0 = ANIMS.idle[0];
for (let y = 0; y < 24; y++) for (let x = 0; x < 24; x++) bust.set(x, y, idle0.get(x + 2, y + 2));

/* ---- metadata ---- */
// Empty rows under the shoes in the standing pose: the app uses it to put the feet exactly on the taskbar edge.
let lowest = 0;
for (let y = 0; y < FH; y++) for (let x = 0; x < FW; x++) if (ANIMS.idle[0].get(x, y)[3]) lowest = Math.max(lowest, y);
const footPad = FH - 1 - lowest;
const BUST = bust.w;

const meta = `/* AUTO-GENERATED by scripts/sprites/build-sprites.mjs – do not edit. */
export const SPRITE_FRAME_W = ${FW};
export const SPRITE_FRAME_H = ${FH};
export const SPRITE_COLS = ${cols};
export const SPRITE_ROWS = ${rows};
/** Transparent rows below the shoes in the standing pose. */
export const SPRITE_FOOT_PAD = ${footPad};
/** Width/height of mascot-bust.png. */
export const SPRITE_BUST = ${BUST};
export const SPRITE_ANIMS = {
${names.map((n, r) => `  ${n}: { row: ${r}, frames: ${ANIMS[n].length}, fps: ${FPS[n] ?? 6} },`).join('\n')}
} as const;
export type SpriteAnim = keyof typeof SPRITE_ANIMS;
`;

/* ---- behaviours (validated, then emitted as typed data) ---- */
const MOVES = ['none', 'walk', 'run', 'dash', 'toCursor', 'fromCursor', 'toEdge'];
const FXS = ['none', 'hop', 'bounce', 'spin', 'backflip', 'upsideDown', 'shake', 'float', 'wobble'];
const fail = (id, msg) => {
  throw new Error(`behaviors.mjs: "${id}": ${msg}`);
};
const seenIds = new Set();
for (const b of BEHAVIORS) {
  if (!b.id || seenIds.has(b.id)) fail(b.id, 'missing or duplicate id');
  seenIds.add(b.id);
  if (!ANIMS[b.anim]) fail(b.id, `unknown anim "${b.anim}"`);
  if (b.arrive && !ANIMS[b.arrive]) fail(b.id, `unknown arrive anim "${b.arrive}"`);
  if (!Array.isArray(b.weight) || b.weight.length !== 3 || b.weight.some((w) => !(w >= 0))) fail(b.id, 'weight must be [calm, bored, sleepy] >= 0');
  if (!Array.isArray(b.duration) || b.duration.length !== 2 || !(b.duration[0] >= 0) || b.duration[1] < b.duration[0]) fail(b.id, 'duration must be [min, max] ms');
  if (b.move && !MOVES.includes(b.move)) fail(b.id, `unknown move "${b.move}"`);
  if (b.fx && !FXS.includes(b.fx)) fail(b.id, `unknown fx "${b.fx}"`);
  if (b.face && !['travel', 'random', 'keep'].includes(b.face)) fail(b.id, `unknown face "${b.face}"`);
  if (b.until && b.until !== 'activity') fail(b.id, `unknown until "${b.until}"`);
  if (b.lines) {
    if (!(b.lines.chance >= 0 && b.lines.chance <= 1)) fail(b.id, 'lines.chance must be 0..1');
    if (!b.lines.en?.length || !b.lines.tr?.length) fail(b.id, 'lines need both en and tr');
  }
}
for (const required of ['idle', 'run', 'wave', 'sleep', 'stretch', 'drag', 'jump']) if (!ANIMS[required]) throw new Error(`frames.mjs must define the "${required}" animation (the engine relies on it)`);
if (!BEHAVIORS.some((b) => b.until === 'activity')) throw new Error('behaviors.mjs needs a behaviour with until: "activity" (falling asleep)');

const behaviorsTs = `/* AUTO-GENERATED by scripts/sprites/build-sprites.mjs from scripts/sprites/behaviors.mjs – do not edit. */
import type { SpriteAnim } from './mascot.meta';

export type Move = 'none' | 'walk' | 'run' | 'dash' | 'toCursor' | 'fromCursor' | 'toEdge';
export type Fx = 'none' | 'hop' | 'bounce' | 'spin' | 'backflip' | 'upsideDown' | 'shake' | 'float' | 'wobble';

export interface BehaviorLines {
  chance: number;
  when?: 'always' | 'bored';
  en: readonly string[];
  tr: readonly string[];
}

export interface Behavior {
  id: string;
  anim: SpriteAnim;
  arrive?: SpriteAnim;
  /** [calm, bored, sleepy] relative probability */
  weight: readonly [number, number, number];
  /** [min, max] ms (travelling behaviours: dwell time after arriving) */
  duration: readonly [number, number];
  move?: Move;
  fx?: Fx;
  face?: 'travel' | 'random' | 'keep';
  until?: 'activity';
  lines?: BehaviorLines;
}

export const BEHAVIORS: readonly Behavior[] = ${JSON.stringify(BEHAVIORS, null, 2)};
`;

fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(path.join(OUT_DIR, 'mascot.png'), encodePNG(sheet));
fs.writeFileSync(path.join(OUT_DIR, 'mascot-bust.png'), encodePNG(bust));
fs.writeFileSync(path.join(OUT_DIR, 'mascot.meta.ts'), meta);
fs.writeFileSync(path.join(OUT_DIR, 'mascot.behaviors.ts'), behaviorsTs);
console.log(`wrote ${path.relative(process.cwd(), OUT_DIR)}: mascot.png ${sheet.w}x${sheet.h}, mascot-bust.png, mascot.meta.ts (${rows} animations), mascot.behaviors.ts (${BEHAVIORS.length} behaviours)`);

/* ---- optional contact sheet ---- */
if (PREVIEW) {
  const K = 4;
  const pad = 6;
  const cellW = FW * K + pad;
  const cellH = FH * K + pad;
  const out = new Bmp(cols * cellW + pad, rows * cellH + pad);
  out.fill(rgba('#4f9d99'));
  names.forEach((n, r) =>
    ANIMS[n].forEach((f, c) => {
      const x = pad + c * cellW;
      const y = pad + r * cellH;
      out.fill(rgba(c % 2 ? '#47918d' : '#4a9692'), x, y, FW * K, FH * K);
      out.paste(scaleNearest(f, K), x, y);
    })
  );
  fs.writeFileSync(PREVIEW, encodePNG(out));
  console.log('preview ->', PREVIEW);
}
